/// The most recent daily digest generated by the backend.
final class DailySummary {
  const DailySummary({required this.date, required this.summary});

  factory DailySummary.fromJson(Map<String, dynamic> json) {
    return DailySummary(
      date: DateTime.parse(json['digest_date'] as String),
      summary: (json['summary'] as String? ?? '').trim(),
    );
  }

  final DateTime date;
  final String summary;
}

/// The summary of a week (Monday to Sunday), written on the Monday after.
final class WeeklySummary {
  const WeeklySummary({
    required this.weekStart,
    required this.summary,
    this.highlights = const [],
    this.people = const [],
    this.conversationCount = 0,
  });

  factory WeeklySummary.fromJson(Map<String, dynamic> json) {
    return WeeklySummary(
      weekStart: DateTime.parse(json['week_start'] as String),
      summary: (json['summary'] as String? ?? '').trim(),
      highlights: [
        for (final item in json['highlights'] as List<dynamic>? ?? const [])
          if (item is String && item.trim().isNotEmpty) item.trim(),
      ],
      people: [
        for (final item in json['people'] as List<dynamic>? ?? const [])
          if (item is Map<String, dynamic> && item['name'] is String) item['name'] as String,
      ],
      conversationCount: json['conversation_count'] as int? ?? 0,
    );
  }

  final DateTime weekStart;
  final String summary;
  final List<String> highlights;

  /// Who came up most, most present first.
  final List<String> people;
  final int conversationCount;
}

/// A voice request Echo is answering, or a photo on its way.
final class WorkingItem {
  const WorkingItem({
    required this.key,
    required this.kind,
    required this.text,
    required this.since,
    this.sessionId,
  });

  factory WorkingItem.fromJson(Map<String, dynamic> json) => WorkingItem(
        key: json['key'] as String,
        kind: json['kind'] as String,
        text: (json['text'] as String? ?? '').trim(),
        since: DateTime.parse(json['since'] as String),
        sessionId: json['session_id'] as String?,
      );

  final String key;

  /// "request" or "photo".
  final String kind;

  /// The command, or the question about the photo ("" for a plain photo).
  final String text;
  final DateTime since;

  /// The chat the answer goes to, when known.
  final String? sessionId;

  bool get isPhoto => kind == 'photo';
}
